const json = items[0].json;

const promptTokens = json.prompt_tokens || 0;
const completionTokens = json.completion_tokens || 0;

// Valores manuais
const precoPrompt = 0.002;
const precoResposta = 0.008;

const custoPrompt = (promptTokens / 1000) * precoPrompt;
const custoResposta = (completionTokens / 1000) * precoResposta;
const custoTotal = custoPrompt + custoResposta;

return [
  {
    json: {
      promptTokens,
      completionTokens,
      custoPrompt: custoPrompt.toFixed(6),
      custoResposta: custoResposta.toFixed(6),
      custoTotal: custoTotal.toFixed(6),
      moeda: "R$"
    }
  }
];

